import{z as E,x as s,o as t,c as h,q as l,j as o,D as e,d as i,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"NCA Noise Contrastive Alignment","description":"","frontmatter":{"title":"NCA Noise Contrastive Alignment","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/nca-align.md","filePath":"llm/nca-align.md","lastUpdated":1791413859000}'),p={name:"llm/nca-align.md"};function C(m,a,_,N,d,B){const r=s("Mermaid");return t(),h("div",null,[a[2]||(a[2]=l('<h1 id="nca-noise-contrastive-alignment" tabindex="-1">NCA Noise Contrastive Alignment <a class="header-anchor" href="#nca-noise-contrastive-alignment" aria-label="Permalink to &quot;NCA Noise Contrastive Alignment&quot;">​</a></h1><div class="epigraph"><p>显式标量奖励不必先压成谁赢谁输；噪声对比估计可以直接从带分的多条回答里抽出策略，而 pairwise DPO 只是其中 $K=2$、温度趋于零的特例。</p><footer>—— Chen 等，Noise Contrastive Alignment of Language Models with Explicit Rewards，NeurIPS 2024</footer></div><p>UltraFeedback 一类数据往往给同一提示打出 \\(K\\gt 2\\) 条回答和标量分，再被裁成最高分对随机一条，送进 <a href="/llm/dpo">DPO</a>。中间两条次优回答和分值都被扔掉。Chen 等人用噪声对比估计（NCE / InfoNCE）把对齐接回生成模型里的对比学习：InfoNCA 把「哪一条更像最优策略的样本」写成多类交叉熵，DPO 是它在成对、硬标签下的极限；NCA 则用二元 NCE，优化每条回答的绝对隐含奖励，用来对付 DPO 训练中喜欢侧似然一路下降的现象。两者都能吃奖励数据集和偏好数据集。本篇按论文把 InfoNCA 与 NCA 放在同一框架里写，标题沿用作者强调的 NCA 这一支。</p><p><span class="marginnote">噪声对比估计（NCE）的直觉：让模型当「侦探」，判断一条回答是真数据还是噪声策略生成的；分得越清，说明模型把真实分布刻得越准。对比学习一族（InfoNCE 是代表）都在做这件事，NCA 的贡献是把对齐目标写成这族的标准成员。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>KL 正则的最优策略满足 \\(\\pi^*(y\\mid x)\\propto \\mu(y\\mid x)\\exp(r(x,y)/\\alpha)\\)。DPO 假定只有成对比较、奖励未给出，于是用 Bradley–Terry 消掉配分函数。若数据集已经有 \\(r_i\\)，先把 \\(r\\) 二值化再 DPO，既损失幅度信息，也损失「同一 \\(x\\) 下多条次优」的对照。组合地枚举所有对再跑 DPO，论文实验表明仍不如直接在 \\(K\\) 条上做多类或 NCE 目标。</p><p>另一条裂缝是似然下降。DPO / InfoNCA 校准的是相对奖励：只要 \\(r_w-r_l\\) 变大，两边一起下降也合法。这与最大似然训练的直觉冲突，在数学与代码这类需要维持正确答案绝对概率的任务上更危险。NCA 把模型定义成 \\(\\pi_\\theta(y\\mid x)=\\mu(y\\mid x)\\exp(r_\\theta(x,y))\\)（等式而非正比），迫使 \\(r_\\theta\\) 在 \\(\\mu\\) 下自归一，从而约束绝对尺度。</p><p><span class="marginnote">「喜欢侧似然下降」的直观版：DPO 只看差值，所以「赢家概率从 0.9 掉到 0.01、输家从 0.1 掉到 0.001」也能让差值变大——两边都在崩，指标却在变好。数学与代码题的答案本身要概率够高才对，NCA 的绝对项就是堵这个漏洞。</span></p><h3 id="相对分类与绝对判别" tabindex="-1">相对分类与绝对判别 <a class="header-anchor" href="#相对分类与绝对判别" aria-label="Permalink to &quot;相对分类与绝对判别&quot;">​</a></h3><p>InfoNCE 在一条锚与一组样本里做多类分类；NCE 对「这条来自数据还是噪声」做二元分类。对齐里，InfoNCA 问的是「\\(K\\) 条里哪条更像 \\(\\pi^*\\)」；NCA 问的是「这一条相对噪声策略应不应该提高绝对奖励」。前者自然包含 DPO，后者针对似然塌缩。不要把 NCA 理解成「又一个 InfoNCE 的别名」。</p><p><span class="marginnote">公式里的 \\(\\mu\\) 是参考策略，与 DPO 的 \\(\\pi_{\\mathrm{ref}}\\) 同类。\\(r_\\theta=\\beta\\log(\\pi_\\theta/\\mu)\\)。\\(\\alpha\\) 是奖励温度，控制软标签的锋利程度，不是 \\(\\beta\\)。两个温度不要合成一个超参。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>InfoNCA 把数据集奖励做成软标签，把 \\(r_\\theta\\) 做成 logits：</p> \\[\\mathcal{L}^{\\mathrm{InfoNCA}}=-\\sum_{i=1}^{K}\\frac{e^{r_i/\\alpha}}{\\sum_j e^{r_j/\\alpha}}\\log\\frac{e^{r_\\theta(x,y_i)}}{\\sum_j e^{r_\\theta(x,y_j)}}. \\]<p>\\(K=2\\) 且 \\(\\alpha\\to 0\\) 时软标签变成 one-hot 赢家，目标退化为 DPO 的 \\(-\\log\\sigma(r_w-r_l)\\)。\\(\\alpha\\gt 0\\) 时次优回答仍按 softmax 权重贡献梯度，\\(K\\) 增大相当于用更多样本估计配分。NCA 的奖励数据损失为</p> \\[\\mathcal{L}^{\\mathrm{NCA}}=-\\sum_{i=1}^{K}\\Biggl[\\frac{e^{r_i/\\alpha}}{\\sum_j e^{r_j/\\alpha}}\\log\\sigma\\bigl(r_\\theta(x,y_i)\\bigr)+\\frac1K\\log\\sigma\\bigl(-r_\\theta(x,y_i)\\bigr)\\Biggr]. \\]<p>第一项按奖励软权重抬绝对 \\(r_\\theta\\)，第二项是对所有候选均匀的降权正则。成对偏好（\\(K=2,\\alpha\\to 0\\)）时 NCA 写成 \\(-\\log\\sigma(r_w)-\\frac12\\sum_{y\\in\\{y_w,y_l\\}}\\log\\sigma(-r_\\theta(x,y))\\)，没有 DPO 那种纯差形式。作者在 Mistral-7B 与 Mixtral-8×7B、UltraFeedback 上比较：有标量分时 InfoNCA / NCA 优于把数据剪成对的 DPO / <a href="/llm/ipo">IPO</a> / <a href="/llm/kto">KTO</a>；只有成对时，NCA 在数学与代码上明显好于 DPO，并给出喜欢侧似然不再下降的曲线。\\(K\\) 从 2 增到 4，两种方法都升，说明次优回答有用。</p>',17)),(t(),o(A,null,{default:e(()=>[n(r,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20Data%5B%22K%20%E6%9D%A1%E5%9B%9E%E7%AD%94%20%2B%20%E6%A0%87%E9%87%8F%20r%20%E6%88%96%E6%88%90%E5%AF%B9%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20Soft%5B%22%E5%A5%96%E5%8A%B1%20softmax%20%E8%BD%AF%E6%A0%87%E7%AD%BE%22%5D%0A%20%20Data%20--%3E%20RT%5B%22r%CE%B8%20%3D%20%CE%B2%20log(%CF%80%CE%B8%2F%CE%BC)%22%5D%0A%20%20Soft%20--%3E%20I%5B%22InfoNCA%EF%BC%9A%E5%A4%9A%E7%B1%BB%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20RT%20--%3E%20I%0A%20%20Soft%20--%3E%20N%5B%22NCA%EF%BC%9A%CF%83(r%CE%B8)%20%E6%8A%AC%E5%8D%87%20%2B%20%CF%83(%E2%88%92r%CE%B8)%20%E6%AD%A3%E5%88%99%22%5D%0A%20%20RT%20--%3E%20N%0A%20%20I%20--%3E%20PI%5B%22%CF%80%CE%B8%22%5D%0A%20%20N%20--%3E%20PI%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="为何-nca-能托住喜欢侧似然" tabindex="-1">为何 NCA 能托住喜欢侧似然 <a class="header-anchor" href="#为何-nca-能托住喜欢侧似然" aria-label="Permalink to &quot;为何 NCA 能托住喜欢侧似然&quot;">​</a></h3><p>InfoNCA 的 softmax 对 \\(r_\\theta\\) 平移不变，绝对高度自由。NCA 的 \\(\\log\\sigma(r_\\theta)\\) 在 \\(r_\\theta\\) 为负且绝对值大时斜率仍在，会把过低的绝对奖励拉回来；均匀的 \\(\\log\\sigma(-r_\\theta)\\) 防止全部抬到饱和。两者的合力使高奖励样本的 \\(r_\\theta\\) 停在正区附近，而不是相对赢家、绝对全负。论文把它联系到 NCE 对归一化常数的估计，而不是经验调参。成对版本里赢家有一项专门的 \\(\\log\\sigma(r_w)\\)，输家没有对称的「必须抬」，因此仍能拉开，但不会靠把两边一起扔进负对数概率来作弊。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="次优回答提供的是配分信息" tabindex="-1">次优回答提供的是配分信息 <a class="header-anchor" href="#次优回答提供的是配分信息" aria-label="Permalink to &quot;次优回答提供的是配分信息&quot;">​</a></h3><p>\\(\\pi^*\\propto\\mu e^{r/\\alpha}\\) 的配分 \\(Z(x)\\) 无法从一条赢家读出。\\(K\\) 条带分样本给出 \\(Z\\) 的蒙特卡洛近似。剪成一对等于用极粗糙的 \\(Z\\)。这与 Best-of-N 只保留上尾相反：对齐训练需要下尾来告诉模型「什么不该提高」，也需要中间带把软标签校准。组合 DPO（所有对都当独立比较）重复计算且没有共享的多类归一化，所以论文说它是次优利用。</p>',5)),(t(),o(A,null,{default:e(()=>[n(r,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%90%8C%E4%B8%80%E6%8F%90%E7%A4%BA%20x%20%E7%9A%84%20K%20%E6%9D%A1%E5%B8%A6%E5%88%86%E5%9B%9E%E7%AD%94%22%5D%20--%3E%20CUT%5B%22%E5%89%AA%E6%88%90%E4%B8%80%E5%AF%B9%3A%20%E5%8F%AA%E7%95%99%E6%9C%80%E9%AB%98%E5%88%86%20vs%20%E9%9A%8F%E6%9C%BA%E4%B8%80%E6%9D%A1%22%5D%0A%20%20CUT%20--%3E%20Z1%5B%22Z%20%E4%BC%B0%E8%AE%A1%E6%9E%81%E7%B2%97%E7%B3%99%20%E2%86%92%20%E5%8F%AA%E5%89%A9%E7%9B%B8%E5%AF%B9%E7%9B%AE%E6%A0%87%22%5D%0A%20%20X%20--%3E%20KEEP%5B%22K%20%E6%9D%A1%E5%85%A8%E4%BF%9D%E7%95%99%22%5D%0A%20%20KEEP%20--%3E%20Z2%5B%22K%20%E6%9D%A1%20%3D%20Z%20%E7%9A%84%E8%92%99%E7%89%B9%E5%8D%A1%E6%B4%9B%E8%BF%91%E4%BC%BC%22%5D%0A%20%20KEEP%20--%3E%20MID%5B%22%E4%B8%AD%E9%97%B4%E5%B8%A6%E6%A0%A1%E5%87%86%E8%BD%AF%E6%A0%87%E7%AD%BE%20%E4%B8%8B%E5%B0%BE%E5%AE%9A%E4%B9%89%E3%80%8C%E4%B8%8D%E8%AF%A5%E6%8F%90%E9%AB%98%E3%80%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p>InfoNCA 在指令跟随的 GPT-4 评估上可以略高于 NCA；NCA 的优势写在推理任务与似然曲线上。没有「永远用 NCA」的结论。奖励噪声大时，软标签 \\(e^{r/\\alpha}\\) 会把错误幅度放大，\\(\\alpha\\) 要加大以抹平；\\(\\alpha\\to 0\\) 则回到硬赢家，信息再次丢掉。</p><p><span class="marginnote">NCA 的第二项对 \\(K\\) 条候选均匀降权，候选必须是同提示下的真实回答，不能拿随机词表噪声去充 \\(K\\)。随机负例的 \\(r_\\theta\\) 已经极低，\\(\\sigma(-r_\\theta)\\) 饱和，只会污染均值。</span></p><h3 id="与-kto、apo-的绝对项同族但推导不同" tabindex="-1">与 KTO、APO 的绝对项同族但推导不同 <a class="header-anchor" href="#与-kto、apo-的绝对项同族但推导不同" aria-label="Permalink to &quot;与 KTO、APO 的绝对项同族但推导不同&quot;">​</a></h3><p><a href="/llm/kto">KTO</a> 用前景价值把单条 \\(r_\\theta\\) 推向参考点上下；<a href="/llm/apo">APO</a> 用 \\(\\sigma(r_w)\\) 规定成对几何。NCA 来自 NCE 判别「数据对噪声」，绝对项有配分与噪声分布的含义。成对 NCA 看起来像「DPO 拆开再加一项压低」，来源不是随意加正则。迁移超参时不要把 KTO 的 \\(\\lambda_D,\\lambda_U\\) 抄到 NCA 的 \\(1/K\\) 上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>有标量分且 \\(K\\gt 2\\) 时，InfoNCA / NCA 才发挥数据利用率；只有成对时 InfoNCA 即 DPO，值得试的是 NCA。两者都要参考 \\(\\mu\\) 与 \\(\\beta\\)，前向与 DPO 同级，另加 \\(K\\) 条的 softmax。\\(K\\) 受显存限制，同一提示的多条回答要对齐 padding。奖励模型的尺度必须与 \\(\\alpha\\) 匹配：分是 0/1 还是百分制，softmax 形状完全不同，应先标准化再扫 \\(\\alpha\\)。</p><p><span class="marginnote">\\(\\alpha\\) 如何改软标签，代个数字：三条回答分 10、9、0。\\(\\alpha=1\\) 时 softmax 权重约 73% : 26% : 0%，接近硬标签；\\(\\alpha=10\\) 时变成约 44% : 40% : 16%，次优回答分到可观梯度。若分是 0–100 的百分制不先归一化，\\(e^{r/\\alpha}\\) 会溢出成近乎 one-hot，\\(\\alpha\\) 扫遍也无效。</span></p><p>它不是在线 RL，不采样新回答。次优回答若来自完全不同的模型族，作为 \\(\\mu\\) 下的噪声对照会错位。论文保证的是理想条件下收敛到最优策略的理论命题，有限 \\(K\\) 与错指定奖励时只是启发式。</p><p><span class="marginnote">「NCA 防止喜欢侧似然下降」是相对 DPO 曲线的观察，不是似然必须上升。正则项仍在压。评估应以任务指标为准，不要把训练曲线上的 \\(\\log\\pi(y_w)\\) 当成对齐成功。</span></p><h3 id="何时不必上-nca" tabindex="-1">何时不必上 NCA <a class="header-anchor" href="#何时不必上-nca" aria-label="Permalink to &quot;何时不必上 NCA&quot;">​</a></h3><p>数据已是干净成对、任务对绝对似然不敏感（短对话、风格偏好），DPO 足够。没有参考模型时，框架未定义。需要组内在线优势时，走 <a href="/llm/grpo">GRPO</a> / <a href="/llm/rloo">RLOO</a>，不要把离线 NCE 假装成策略梯度。只有二元点赞没有标量分也没有成对，KTO 更贴数据形态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NCA / InfoNCA 用噪声对比把显式奖励数据集直接接到策略；不必先剪成偏好对。</li><li>InfoNCA 是多类交叉熵，\\(K=2,\\alpha\\to 0\\) 即 DPO；NCA 是二元 NCE，约束绝对 \\(r_\\theta\\)，缓解喜欢侧似然下降。</li><li>次优回答用于估计配分，增大 \\(K\\) 在论文里带来稳定收益。</li><li>\\(\\alpha\\) 是奖励温度，\\(\\beta\\) 是 KL 对数比系数，二者分工。</li><li>成对设定下 NCA 在数学与代码上优于 DPO；指令跟随上 InfoNCA 可以更强。</li><li>框架仍要参考策略，不是无参考方法。</li><li>出处：Chen, He, Yuan, Cui, Su, Zhu，<em>Noise Contrastive Alignment of Language Models with Explicit Rewards</em>，NeurIPS 2024，arXiv:2402.05369。</li></ul>',13))])}const g=E(p,[["render",C]]);export{D as __pageData,g as default};
